'use client';
import { useState, useEffect } from 'react';
import { useRouter, useParams } from 'next/navigation';
import { ShieldCheck, Lock } from 'lucide-react';
import { Outfit } from 'next/font/google';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle, CardDescription, CardFooter } from "@/components/ui/card";

const outfit = Outfit({ subsets: ['latin'] });

export default function AdminLogin() {
  const router = useRouter();
  const params = useParams();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const adminPath = params?.adminPath || 'admin';

  useEffect(() => {
    // Auto-redirect if already logged in
    const auth = localStorage.getItem('admin_auth');
    if (auth) {
      router.push(`/${adminPath}`);
    }
  }, [router, adminPath]);

  const handleLogin = (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    
    // Simulate network delay for effect
    setTimeout(() => {
        if (username === 'admin' && password === 'admin123') { 
            // Set a cookie or localStorage to persist admin session
            localStorage.setItem('admin_auth', 'true');
            document.cookie = "admin_auth=true; path=/";
            router.push(`/${adminPath}`);
        } else {
            setError('Invalid Credentials');
            setLoading(false);
        }
    }, 800);
  };

  return (
      <main className={`admin-root min-h-screen flex items-center justify-center relative overflow-hidden ${outfit.className}`}>
        {/* Background Gradients */}
        <div className="absolute top-[-20%] left-[-10%] w-[50%] h-[50%] bg-primary/20 rounded-full blur-[120px] pointer-events-none"></div>
        <div className="absolute bottom-[-20%] right-[-10%] w-[50%] h-[50%] bg-secondary/20 rounded-full blur-[120px] pointer-events-none"></div>

        <Card className="w-full max-w-[400px] border-border/50 bg-background/50 backdrop-blur-xl shadow-2xl z-10">
            <CardHeader className="text-center pb-2">
                <div className="mx-auto mb-4 bg-primary/10 p-4 rounded-full w-20 h-20 flex items-center justify-center ring-1 ring-primary/20 shadow-lg shadow-primary/10">
                    <ShieldCheck className="w-10 h-10 text-primary" />
                </div>
                <CardTitle className="text-2xl font-bold tracking-tight">Admin Portal</CardTitle>
                <CardDescription>Enter your credentials to access the secure area</CardDescription>
            </CardHeader>
            <CardContent>
                <form onSubmit={handleLogin} className="space-y-4">
                    <div className="space-y-2">
                        <Input 
                            type="text" 
                            placeholder="Username" 
                            value={username}
                            onChange={(e) => setUsername(e.target.value)}
                            className="bg-secondary/50 border-input/50 focus-visible:ring-primary h-12"
                        />
                    </div>
                    <div className="space-y-2">
                        <Input 
                            type="password" 
                            placeholder="Password" 
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            className="bg-secondary/50 border-input/50 focus-visible:ring-primary h-12"
                        />
                    </div>
                    {error && (
                        <div className="p-3 rounded-lg bg-destructive/10 text-destructive text-sm font-medium text-center border border-destructive/20 animate-in fade-in slide-in-from-top-1">
                            {error}
                        </div>
                    )}
                    <Button 
                        type="submit" 
                        disabled={loading}
                        className="w-full h-12 text-base font-semibold shadow-lg shadow-primary/20 hover:shadow-primary/30 transition-all"
                    >
                        {loading ? (
                            <div className="flex items-center gap-2">
                                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                                Authenticating...
                            </div>
                        ) : (
                            <div className="flex items-center gap-2">
                                <Lock className="w-4 h-4" /> Secure Login
                            </div>
                        )}
                    </Button>
                </form>
            </CardContent>
            <CardFooter className="flex justify-center border-t border-border/50 pt-6">
                <p className="text-xs text-muted-foreground">Protected by Suvidha Secure Systems &copy; 2026</p>
            </CardFooter>
        </Card>
      </main>
  );
}
